INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein ERM nur für relationale Datenbanken geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere DBs konzeptionell nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem ERM?', 3, '[{"text": "Datenbankstruktur planen", "correct": true, "because": "Definiert Entitäten und Beziehungen"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "UI gestalten", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem ERM?', 5, '[{"text": "Entitäten", "correct": true, "because": "Repräsentieren Objekte"}, {"text": "Beziehungen", "correct": true, "because": "Verbinden Entitäten"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entitäten haben Attribute. b) Beziehungen sind immer physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beziehungen sind konzeptionell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem ERM?', 4, '[{"text": "Entitäten", "correct": false, "because": "Kern des Modells"}, {"text": "Beziehungen", "correct": false, "because": "Verbinden Entitäten"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Modellierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ERM auch technische Details zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Konzeptionelle Ebene"}, {"text": "Ja", "correct": false, "because": "Nicht implementierungsspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Entität?', 3, '[{"text": "Rechteck", "correct": true, "because": "UML-Standard für Entitäten"}, {"text": "Pfeil", "correct": false, "because": "Nur Beziehungen"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem ERM?', 5, '[{"text": "Attribute", "correct": true, "because": "Beschreiben Entitäten"}, {"text": "Kardinalitäten", "correct": true, "because": "Definieren Beziehungen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "UI-Layout", "correct": false, "because": "Kein Modellierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ERM ist für Datenbankdesign wichtig. b) Es zeigt Abläufe. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abläufe sind Aktivitätsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein ERM?', 4, '[{"text": "Entitäten", "correct": false, "because": "Grundbausteine"}, {"text": "Beziehungen", "correct": false, "because": "Verbinden Entitäten"}, {"text": "Methodenaufrufe", "correct": true, "because": "Sequenzdiagramm-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein ERM nur für Softwareentwicklung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Geschäftsdaten"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen definiere ich im ERM?', 4, '[{"text": "1:n", "correct": true, "because": "Eine-zu-viele"}, {"text": "n:m", "correct": true, "because": "Viele-zu-viele"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ERM nur für große Datenbanken ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine DBs profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierung unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem ERM?', 3, '[{"text": "Klarheit der Beziehungen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ERM zeigt Entitäten und Beziehungen. b) Es ist für Hardwareplanung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein ERM?', 5, '[{"text": "Datenstrukturübersicht", "correct": true, "because": "Klarheit über Entitäten"}, {"text": "Beziehungsplanung", "correct": true, "because": "Verknüpfungen sichtbar"}, {"text": "Datenflussanalyse", "correct": false, "because": "Anderes Diagramm"}, {"text": "UI-Design", "correct": false, "because": "Kein Modellierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im ERM unwichtig?', 3, '[{"text": "Kardinalitäten", "correct": false, "because": "Definieren Beziehungen"}, {"text": "Attribute", "correct": false, "because": "Beschreiben Entitäten"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Modellierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein ERM auch Abläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Statisch, keine Prozesse"}, {"text": "Ja", "correct": false, "because": "Abläufe in Aktivitätsdiagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ERM für Tests nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Testdatenstruktur ableitbar"}, {"text": "Nein", "correct": false, "because": "Basis für Testfälle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Beziehung im ERM?', 4, '[{"text": "Raute", "correct": true, "because": "UML-Standard für Beziehungen"}, {"text": "Rechteck", "correct": false, "because": "Nur Entitäten"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]');
